import{_ as a,a as t}from"./chunks/3176b2becf2e994ce064.I2RTMoFM.js";import{_ as o,C as i,o as l,c as n,j as e,a as s,E as h,a6 as c}from"./chunks/framework.CnPv4DE1.js";const q=JSON.parse('{"title":"自我提升者正在网上开创自己的事业（方法如下）","description":"","frontmatter":{"title":"自我提升者正在网上开创自己的事业（方法如下）","originalTitle":"Self Improvers Are Creating Their Own Careers Online (Here’s How)","date":"2023-04-07","originalUrl":"https://thedankoe.com/letters/self-improvers-are-creating-their-own-career-heres-how/","minutes":12,"sourceHash":"e0b2c58e2ac235f28a7283ee1b4175d896683f7d2e10b35bc4acb92e9dbe39c0","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/self-improvers-are-creating-their-own-career-heres-how/"}]]},"headers":[],"relativePath":"letters/self-improvers-are-creating-their-own-career-heres-how.md","filePath":"letters/self-improvers-are-creating-their-own-career-heres-how.md"}'),d={name:"letters/self-improvers-are-creating-their-own-career-heres-how.md"};function f(m,p,u,b,g,k){const r=i("ArticleMeta");return l(),n("div",null,[p[0]||(p[0]=e("h1",{id:"自我提升者正在网上开创自己的事业-方法如下",tabindex:"-1"},[s("自我提升者正在网上开创自己的事业（方法如下） "),e("a",{class:"header-anchor",href:"#自我提升者正在网上开创自己的事业-方法如下","aria-label":'Permalink to "自我提升者正在网上开创自己的事业（方法如下）"'},"​")],-1)),h(r),p[1]||(p[1]=c('<p>醒来。</p><p>按了4次小睡按钮。</p><p>盯着手机看。</p><p>滚出被窝。</p><p>泡咖啡。</p><p>堵在路上。</p><p>做8小时毫无成就感的工作。</p><p>再次……堵在路上。</p><p>和你的“另一半”吵架。</p><p>遛宠物。</p><p>看电视。</p><p>昏睡过去。</p><p>重复。</p><p>这应该会把你吓得半死。</p><p>这是95%的人口的生活状态。</p><p>即使是那些每天都在努力逃离的人，也无法挣脱。</p><p>我拼尽全力去避免朝九晚五的生活。</p><p>我从18岁到22岁一直在创业，却一分钱也没赚到。（但那是我打发时间极其有趣的一种方式）。</p><p>当我终于找到一份工作时，上面那个列表就成了我被设定的生活状态。</p><p>我无法控制自己如何安排一天中的10个小时。</p><p>无论我是否愿意，一切都围绕着我的工作转。</p><p>在过去三四年的创作者旅程中，我意识到了几件事：</p><ul><li>创业是长期逻辑思考者的唯一出路</li><li>人类从一开始就在消除体力劳动（而且我们正处于彻底消除它的前沿）</li><li>创作者经济是新经济。如果你没有个人品牌，你就输了。就像《黑镜》里“急转直下”（Nosedive）那一集，不过是往好的方向发展。</li><li>明智的人通过做自己喜欢的事情来赚钱（向走在时代前沿的艾伦·瓦茨 Alan Watts 致敬）。</li></ul><p>未来属于自我提升者。</p><p>属于那些对自己的未来负责，并成为周围人价值源泉的人。</p><p>当你在公开场合做这件事时，几乎不可能赚不到钱。</p><p>这就是我们今天要讨论的内容。</p><h2 id="创业被高估了" tabindex="-1">“创业被高估了” <a class="header-anchor" href="#创业被高估了" aria-label="Permalink to &quot;“创业被高估了”&quot;">​</a></h2><p>前几天我在刷YouTube时，一个帖子引起了我的注意。</p><p>它问：“有哪些大家都喜欢但你觉得被高估了的东西？”</p><p>有些评论提到了旅行，</p><p>但这一条引起了我的注意：</p><p><img src="'+a+'" alt=""></p><p><img src="'+t+'" alt=""></p><p>说实话，这起初惹恼了我。</p><p>人们怎么会意识不到创业是完全掌控自己生活的唯一途径呢？</p><p>而完全掌控是获得持久快乐的唯一途径？</p><p>但是，想要找到一份能让你持续利用杠杆撬动所有让生活变得美好的内在驱动力（好奇心、激情、目标、自主性和精通）的“完美”工作，正变得越来越困难。</p><p>我突然明白了几件事：</p><p><strong>人们讨厌他们不理解的东西。</strong></p><p>他们只看到了创业者生活的5%，就认为足以得出结论并封闭自己的思想。好奇心在这一刻消失殆尽。</p><p>他们认为创业被高估了，因为他们不是创业者。</p><p><strong>“我厌倦了</strong> <strong>被称为</strong> <strong>工资奴隶。”</strong></p><p>抱歉，但你的感觉不是现实。</p><p>如果你被解雇了交不起账单，你就会被迫为了生存而工作。你别无选择。无论你是否喜欢这个称呼，从定义上来说，你就是一个工资奴隶。</p><p>不仅如此，大多数人并没有意识到幕后正在发生的剥削。留在你那掠夺性的朝九晚五工作中，你就是在助长对血汗工厂工人的剥削，并在积极阻碍人类进化。（当然，并非所有情况都是如此。仔细想想你在为谁工作）。</p><p><strong>“我向已经发展成熟的企业提供我的技能有什么错？”</strong></p><p>没毛病。</p><p>但为什么要让你所获得的技能受制于一份重复且收入有上限的职业呢？</p><p>为什么不发挥你独特的兴趣，并作为一家企业把这些技能卖给成熟的公司呢？</p><p>这样你就不会成为某些生产力指标的奴隶，你可以建立自己的系统，接纳更多的客户，用更少的工作赚到上班时5倍的钱。</p><p>和往常一样，所有这些都归结为由社会环境塑造的身份所强加的狭隘视角。</p><p>或者，他们对什么是创业有着狭隘的看法。</p><p><strong>“你付给一个男人50美元来逃离母体（matrix），事情不是这样运作的。”</strong></p><p>我对泰特（Tate）或他的产品不感兴趣，但花50美元学习经过时间考验的适销技能，总比花4万美元拿个过时的学位被训练进入“母体”要好。</p><p><strong>创业者不会回到朝九晚五的生活。</strong></p><p>我从未听说过有人放弃成功的创业项目去重新过朝九晚五的日子。但我却总是听说朝九晚五的打工族为了更好的生活而离开他们的职业。</p><p><strong>“你总是很忙。”</strong></p><p>不，你并没有。</p><p>创业的全部意义在于减少你的工作量，并优先考虑生活中更美好的事物。如果你整天都在工作，那不是因为你是创业者，而是因为你缺乏自我管理能力。</p><p>我（在大多数时间）每天工作<a href="https://thedankoe.com/the-4-hour-workday-focused-work-changed-my-life/" target="_blank" rel="noreferrer">4小时</a>，然后就强制自己停下来。因为我知道我的工作质量反而会提高。</p><p><strong>创业的心理学。</strong></p><p>我们的祖先在他们的部落中就是创业者。</p><p>而你的心理结构并不是为了保持停滞不前而设计的。</p><p>你可以做任何你想做的事，但我相信任何人的最终目标都是创业。</p><p>为什么？因为你的心智需要通过进化来获得满足感。它需要不断增加的挑战，而不是真正地“通关游戏”。</p><p>在企业的权力阶梯上，你不可避免地会到达一个挑战不再存在的位置。你会变得温顺、安逸，并习惯于平庸的生活（并且你会<em>认为</em>生活本该如此）。</p><p>深刻和意义存在于未知之中，而创业就是你潜入海洋深处的潜水艇。</p><p><strong>工作消耗了你生命中大约25%的时间。</strong></p><p>如果你不自己创造一项事业，你就会被分配一份工作。</p><p>如果你对你的工作没有激情，那你生命中的25%就没有激情。大多数人对他们生命中另外的75%也没有激情。</p><p>我们的事业、目标或使命，是我们以一种有影响力的方式将注意力投入到现实中的方式。它让我们免于发疯。</p><p>坦率地说，我们不能为了正念修行而将一生的注意力都集中在呼吸、身体或自然上。必须有一个平衡，但我们的注意力必须与现实结合起来，以防止大脑陷入混乱状态。</p><p>朝九晚五只是一块垫脚石。</p><p>我对朝九晚五没什么意见，但它是一种手段，而不是终点。</p><p>利用你的工作去获取技能、知识和地位，从而让你能够创造你想要的东西。</p><h2 id="劳动的消亡" tabindex="-1">劳动的消亡 <a class="header-anchor" href="#劳动的消亡" aria-label="Permalink to &quot;劳动的消亡&quot;">​</a></h2><blockquote><p>真正的AI奇点，如果真的发生的话，不会像科幻小说里那样看起来像一个突然的末日场景。它真正发生的方式——这可能是不可避免的——是人类劳动的逐渐消亡 <a href="https://t.co/gHXoKjZjfk" target="_blank" rel="noreferrer">pic.twitter.com/gHXoKjZjfk</a></p><p>— Zero HP Lovecraft 🦅🐍 (@0x49fa98) <a href="https://twitter.com/0x49fa98/status/1643016730187386880?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">2023年4月3日</a></p></blockquote><p>亚里士多德谴责体力劳动对身体和灵魂有害。</p><p>古希腊人将工作视为生活中不可或缺的一部分。但这仅仅是获得休闲、创造力和沉思的手段，因为他们认为这些才是通往幸福的关键。</p><p>没有工作，休闲就失去了意义，反之亦然。</p><p>生活开始缺乏平衡与对比。</p><p>体力劳动并不总是坏事。但为了生存或地位而完成无意识的任务，让你和机器人或动物没什么两样。</p><p>要创造有意义的工作，我们的努力必须建立在精通感之上。</p><p>你的使命就是你愿意接受的痛苦源泉。</p><p>起初，有奴隶被分配承担大部分的体力劳动。</p><p>后来，拖拉机、风车和自助结账机等工具进一步减轻了负担。</p><p>现在，大多数员工被束缚在格子间里，执行违背他们天性的重复性任务。</p><p>我的信念是，人类已经进化到了不需要人类去干这些“脏活累活”的地步。</p><p>这些年来，自动化和人工智能取得了突飞猛进的发展。</p><p>对此有很多末日猜测，但我只看到了它带来的好处。</p><p>体力劳动的减少要求创造性和知识性工作的增加。</p><p>正如麦肯纳（McKenna）所说：<em>“语言铺了多远的路，思想就能走多远”</em></p><p>如果我们想拓展可能性的边界，我们就必须创造出渗透到文化并影响语言的知识、观念和信仰。这样一来，集体思想就能扩展，呈指数级的进步就能实现。</p><p>在我眼中，工作的未来属于有创造力的人。</p><p>作家。</p><p>演讲者。</p><p>设计师。</p><p>创作者。</p><p>每一个我们曾以为会被AI“取代”的人。</p><p>相反，AI将成为一种工具，让有创造力的人能够突破边界。</p><p>要做好这件事，工作是必要的，但休息和休闲更为重要，这是因为大脑的默认模式网络（Default Mode Network）：</p><blockquote><p>“默认模式网络（DMN）是一系列相互连接的大脑区域，当人们停止集中精力处理外部任务，并且认知从向外聚焦转向向内聚焦时，它就会被激活。”</p></blockquote><p>简而言之，当你不专注于工作时，大脑反而是更加活跃的。</p><p>当我们作为人类，同等重视工作和休息时（不是那种喝红酒、泡泡浴的休息，而是去健身房和散步这种休息），我们就是在为头脑产生新奇的想法做准备。</p><p>而通过互联网的力量，集体知识不断增加，我们的思考能力也随之进化。</p><p>谈点实际的：</p><p>你现在有机会去追求有意义的工作，解锁现代社会长期忽视的大脑部位。</p><p>人类可以带着激情去探索现实，提升自己的技能组合，并获得自我实现。</p><p>工作的未来属于自力更生的人、自我教育的人，以及那些抓住自动化和人工智能带来的创造性机遇的人。</p><p>未来关乎平衡，而不是过度工作。</p><p>未来关乎展现人性，而不是像机器一样。</p><p><a href="https://thedankoe.com/become-a-digital-renaissance-man-and-join-the-new-rich/" target="_blank" rel="noreferrer">数字文艺复兴</a>已经到来。</p><h2 id="创作者经济就是新经济" tabindex="-1">创作者经济就是新经济 <a class="header-anchor" href="#创作者经济就是新经济" aria-label="Permalink to &quot;创作者经济就是新经济&quot;">​</a></h2><p>关于这一点，我已经谈论了一阵子，但 <a href="https://twitter.com/themattmic" target="_blank" rel="noreferrer">马特·米克（Matt Mic）</a>写了一篇令人惊叹的连珠推文（thread），为我的理论带来了一个全新的视角。</p><p>我的理论 = <a href="https://thedankoe.com/the-future-of-the-creator-economy-my-bold-prediction/" target="_blank" rel="noreferrer">工作和教育的未来</a> 将是每个人都将拥有他们自己的创作者业务（或者为创作者工作），这些业务将像公立学校一样发挥作用。</p><p>我要用我自己的评论和结构来总结马特推文里的要点，<a href="https://twitter.com/themattmic/status/1643236796522700801" target="_blank" rel="noreferrer">不过你也可以在这里阅读原文。</a></p><p>首先，我们需要退一步，认识到社交媒体有多么重要。</p><p>是的，它可能是有毒的，但那反映的是个体选择消费这种内容的结果。社交媒体是我生活中一个令人难以置信的加分项（对大多数创作者的生活也是如此，它很少是有毒的）。</p><p>人类是社会性动物。社交媒体通过媒介消除了社交的障碍。</p><p>媒介是我们学习的方式。</p><p>媒介是我们获取新信息的方式。</p><p>媒介是我们传达企业价值的方式。</p><p>媒介占据了我们生活中的很大一部分。它创造了一种社会结构，人们依靠这种结构让文明像现在这样运作。</p><p>附注：我在<a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">数字经济学（Digital Economics）</a>中教授所有这些内容，并附带Notion模板和系统。这是一门关于创作者品牌、内容、产品创建以及面向未来的推广的大师课。</p><h3 id="社交媒体的3个层级" tabindex="-1">社交媒体的3个层级 <a class="header-anchor" href="#社交媒体的3个层级" aria-label="Permalink to &quot;社交媒体的3个层级&quot;">​</a></h3><p>平台构成了数字媒体的第一个层级。</p><p>苹果和谷歌创造了我们拿在手里和放在办公室里的大部分技术。它们为社交媒体奠定了基础。</p><p>第二个层级是像Facebook、Instagram、YouTube和Twitter这样的应用程序。</p><p>这些应用程序捕获了与平台层相同的价值，因为它们拥有数十亿的月活跃用户和数万亿美元的价值。</p><p>在过去的十年里，一个新的第3层级出现了：</p><p>创作者。</p><p>就像应用程序本身一样，像罗根（Rogan）这样的大咖创作者（在未来十年内）将聚集数十亿的粉丝，并创造数万亿美元的价值。</p><p>创作者们正在“原子化”社交网络所做的事情，通过捕获大众注意力、形成社区、分发媒体和产生收入。</p><h3 id="对人类的需求" tabindex="-1">对人类的需求 <a class="header-anchor" href="#对人类的需求" aria-label="Permalink to &quot;对人类的需求&quot;">​</a></h3><p>随着自动化和人工智能呈指数级增长，人们从人类那里获取媒体内容完全是合情合理的。</p><p>个人品牌。</p><p>那些根据自己兴趣进行教育、娱乐和启发他人的人。</p><p>除非我们重写集体心理（这种心理几百年来都没怎么变过），否则这是不可避免的。人是被人类吸引的，而不是被机器人吸引。</p><p>不过，机器人在减少劳动力和提高人类创造力方面确实有其用武之地。</p><h3 id="我的理念" tabindex="-1">我的理念 <a class="header-anchor" href="#我的理念" aria-label="Permalink to &quot;我的理念&quot;">​</a></h3><p>商业是自我的延伸。</p><p>它是承载你目标的容器。</p><p>你的目标会不断演变，你必须解决生活中那些表面的问题，才能触及你最深层的目标。</p><p>这里的规律在于永恒市场（这也是资金流动最多的地方）。</p><p>健康、财富和人际关系。</p><p>通过互联网获取必要的技能和知识，解决你自己的问题。</p><p>将你学到的东西以免费内容和付费产品的形式传递下去。</p><p>通过这样做，你不仅创造了一个独立的收入来源，还创造了巨大的社会杠杆。</p><p>我已经写过大量关于这个主题的文章，但获取这些信息最系统的地方，是我在YouTube上的<a href="https://youtube.com/playlist?list=PLB4ePXk6nBaeG3fD13NaRMsRsEc2iCsV4" target="_blank" rel="noreferrer">一人企业（One Person Business）系列视频</a>。</p><h2 id="创作者变现方法" tabindex="-1">创作者变现方法 <a class="header-anchor" href="#创作者变现方法" aria-label="Permalink to &quot;创作者变现方法&quot;">​</a></h2><p>一旦你<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">建立了受众群体</a>，甚至即使你还没有建立，都有很多变现的方法，但我会在这里按优先级把它们列出来。</p><h3 id="_1-自由职业、辅导或家教" tabindex="-1">1) 自由职业、辅导或家教 <a class="header-anchor" href="#_1-自由职业、辅导或家教" aria-label="Permalink to &quot;1) 自由职业、辅导或家教&quot;">​</a></h3><p>要想从一开始就变现，你需要提供一项服务。</p><p>当你没有充足的流量来获取收入时，构建数字产品、会员制或软件是不可持续的。</p><p>当你创建一个售价在500到1000美元之间的最小可行报价时，你可以使用直接触达策略来销售你的报价。</p><p>一旦你取得了一些成果并提高了价格，你每个月只需要2到3个客户，就能获得比美国平均工资还要高的收入。</p><p>你不需要庞大的受众群体和每月500笔的产品销量来产生收入。</p><p>你该创造什么服务呢？关于创建一个<a href="https://thedankoe.com/the-best-online-business-model-to-make-1-million-in-2023/" target="_blank" rel="noreferrer">最小可行报价</a>，我在这里写过。</p><p>简而言之，提升你自己，然后去打造一个你在自己曾经的旅程中都渴望拥有的东西。</p><p>从你为了实现自我实现而购买的那些产品中汲取灵感。</p><p>然后，去帮助别人做同样的事情。</p><h3 id="_2-训练营与课程" tabindex="-1">2) 训练营与课程 <a class="header-anchor" href="#_2-训练营与课程" aria-label="Permalink to &quot;2) 训练营与课程&quot;">​</a></h3><p>一旦你有了一小群受众和客户成果，你就可以把这些成果转化为训练营形式的课程。</p><p>这样一来，你仍然可以：</p><ul><li>收取更高的价格</li><li>维持可持续的收入</li><li>不需要海量的客户</li></ul><p>基于训练营的课程就是在常规课程的基础上，加上了时间框架、有用的群组通话，以及一个用来解答问题的社区。</p><p>然后，当时机成熟，并且你有了更大的受众群体时，你就可以把它变成一个完整的、让用户自学的自助课程。</p><h3 id="_3-打造任何你想要的东西" tabindex="-1">3) 打造任何你想要的东西 <a class="header-anchor" href="#_3-打造任何你想要的东西" aria-label="Permalink to &quot;3) 打造任何你想要的东西&quot;">​</a></h3><p>现在你有了分发渠道和杠杆，你真的可以卖任何你想要的东西了。</p><ul><li>想创立一个服装品牌？请便。</li><li>想卖像补剂系列这样的实体产品？全凭你做主。</li><li>想放下一切，去开一家实体健身房或咖啡店？尽管去干。</li></ul><p>你有资源让任何商业模式运转起来。</p><p>你的声誉很高。你拥有社会资本。而你的数字产品每个月能为你带来5万到20万美元的收入。</p><p>当然，这是在3到4年的时间尺度上的目标。</p><p>就这样，你开创了自己的事业。</p><p>通过在数字市场上学习、创造和销售，你消除了那些曾经存在于物理世界的障碍。</p><p>未来是光明的，任何想要利用好这一趋势的人都有能力做到。</p><p>商业中永恒的市场是：</p><ul><li>健康</li><li>财富</li><li>人际关系</li><li>幸福</li></ul><p>这些全都是人们直到时间尽头都将面临的迫切的常青问题。</p><p>解决你自己的问题。</p><p>记录下解决方案。</p><p>把它提供给别人。</p><p>获得报酬。</p><p>—— 丹·柯（Dan Koe）</p><hr><p><a href="/en/letters/self-improvers-are-creating-their-own-career-heres-how">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',187))])}const P=o(d,[["render",f]]);export{q as __pageData,P as default};
